  .clock-circle::before, .clock-circle::after {
    content: "";
    position: absolute;
    background: #111;
    left: 50%;
    top: 50%;
    transform-origin: bottom center;
  }
  .clock-circle::before { /* hour hand */
    width: 3px;
    height: 32px;
    transform: translate(-50%, -100%) rotate(60deg);
  }
  .clock-circle::after { /* minute hand */
    width: 2px;
    height: 45px;
    transform: translate(-50%, -100%) rotate(200deg);
  }
  .clock-num {
    position: absolute;
    font-size: 9px;
    color: #333;
