      <div class="seat-label" style="top:15px; left:0px;">1号位<br>主宾</div>
      <div class="seat-label" style="top:8px; left:118px;">2号位<br>第二主宾</div>
      <div class="seat-label" style="top:15px; left:230px;">3号位</div>
